<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500;600&display=swap" rel="stylesheet">
<style>
  :root{
    --bg:#0B1220;
    --panel:#0E1A2B;
    --card:#122036;
    --card-2:#162740;
    --line:rgba(148,178,214,.12);
    --line-strong:rgba(148,178,214,.22);
    --ink:#E9F0F8;
    --ink-2:#C3CFE0;
    --ink-3:#93A5BD;
    --ink-4:#5B718B;
    --sig:#2FD6C4;   /* 在线 / 值班 */
    --busy:#F2B544;  /* 繁忙 */
    --idle:#5B718B;  /* 休眠 */
    --alarm:#F4533D; /* 异常 */
    --s-soft:rgba(47,214,196,.12);
    --b-soft:rgba(242,181,68,.13);
    --a-soft:rgba(244,83,61,.13);
    --font-d:"Space Grotesk","PingFang SC","Microsoft YaHei",sans-serif;
    --font-b:"Inter","PingFang SC","Microsoft YaHei",sans-serif;
    --font-m:"JetBrains Mono",ui-monospace,monospace;
    --radius:16px;
    --shadow:0 20px 48px -24px rgba(0,0,0,.55);
  }
  *{box-sizing:border-box;margin:0;padding:0}
