  .brand-name{font-family:var(--font-d);font-weight:600;font-size:16px;letter-spacing:.02em}
  .brand-name em{font-style:normal;color:var(--sig)}
  .top-nav{display:flex;gap:4px;margin-left:12px;flex:1}
